/**
 * Exact 921-word IELTS Listening & Spelling catalog from the user's original Google Drive project
 * (words.json + audio-manifest.json):
 * - 782 Bundled words with their exact original pronunciation audio CDN URLs
 * - 139 Missing words ready for custom Cloud/Local recordings
 * - Page 1 (447 words) & Page 2 (474 words) across all 32 original categories
 */

export interface WordItem {
  id: string;
  originalId: string;
  word: string;
  bangla: string;
  category: string;
  example: string;
  hasBundledAudio: boolean;
  bundledAudioFile?: string;
  page: 1 | 2;
}

export function toWordId(word: string): string {
  return (
    word
      .normalize("NFKC")
      .toLowerCase()
      .replace(/[‘’]/g, "'")
      .replace(/[‐‑–—]/g, "-")
      .trim()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "") || "word"
  );
}

